#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;
vector<int> spf, radical;

// squarefree divisors d > 1 of a squarefree value, paired with mu(d)
vector<pair<int, int>> factors(int value) {
    vector<pair<int, int>> terms = {{1, 1}};
    while (value > 1) {
        int p = spf[value];
        while (value % p == 0) value /= p;
        for (size_t t = 0, size = terms.size(); t < size; t++) terms.push_back({terms[t].first * p, -terms[t].second});
    }
    terms.erase(terms.begin());
    return terms;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n), qx(q), qy(q);
    for (auto &x : a) cin >> x;
    int limit = *max_element(a.begin(), a.end());
    for (int i = 0; i < q; i++) cin >> qx[i] >> qy[i], limit = max(limit, qy[i]);
    spf.resize(limit + 1);
    iota(spf.begin(), spf.end(), 0);
    for (int p = 2; (long long)p * p <= limit; p++)
        if (spf[p] == p)
            for (int v = p * p; v <= limit; v += p)
                if (spf[v] == v) spf[v] = p;
    radical.assign(limit + 1, 1);
    vector<int> mu(limit + 1, 0);
    mu[1] = 1;
    for (int v = 2; v <= limit; v++) {
        int p = spf[v], quotient = v / p;
        radical[v] = radical[quotient] * (quotient % p == 0 ? 1 : p);
        mu[v] = quotient % p == 0 ? 0 : -mu[quotient];
    }
    vector<long long> powers(n + 1, 1);
    for (int i = 0; i < n; i++) powers[i + 1] = powers[i] * 2 % MOD;
    vector<int> counts(limit + 1, 0);
    for (int x : a)
        for (auto &[d, s] : factors(radical[x])) counts[d]++;
    // good subsequences = sum over squarefree d > 1 of -mu(d) * (2^count[d] - 1)
    long long current = 0;
    for (int d = 2; d <= limit; d++)
        if (counts[d] && mu[d]) current -= mu[d] * (powers[counts[d]] - 1);
    current = ((current % MOD) + MOD) % MOD;
    long long answer = 0;
    for (int i = 0; i < q; i++) {
        int index = qx[i] - 1, value = qy[i], old = a[index];
        if (radical[old] != radical[value]) {
            for (auto [number, delta] : {pair<int, int>{old, -1}, {value, 1}})
                for (auto &[d, s] : factors(radical[number])) {
                    current += s * (powers[counts[d]] - 1);
                    counts[d] += delta;
                    current -= s * (powers[counts[d]] - 1);
                }
            current = ((current % MOD) + MOD) % MOD;
        }
        a[index] = value;
        answer += current;  // the per-update counts are summed without a final modulo
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static final long MOD = 1000000007L;
    static int[] spf;

    // squarefree divisors d > 1 of a squarefree value with mu(d); returns how many were written
    static int factors(int value, int[] div, int[] sign) {
        int size = 1;
        div[0] = 1;
        sign[0] = 1;
        while (value > 1) {
            int p = spf[value];
            while (value % p == 0) value /= p;
            for (int t = 0, s = size; t < s; t++) {
                div[size] = div[t] * p;
                sign[size++] = -sign[t];
            }
        }
        return size; // entry 0 is the divisor 1 and is skipped by callers
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), q = nextInt();
        int[] a = new int[n], qx = new int[q], qy = new int[q];
        int limit = 1;
        for (int i = 0; i < n; i++) limit = Math.max(limit, a[i] = nextInt());
        for (int i = 0; i < q; i++) {
            qx[i] = nextInt();
            limit = Math.max(limit, qy[i] = nextInt());
        }
        spf = new int[limit + 1];
        for (int i = 0; i <= limit; i++) spf[i] = i;
        for (int p = 2; (long) p * p <= limit; p++)
            if (spf[p] == p)
                for (int v = p * p; v <= limit; v += p)
                    if (spf[v] == v) spf[v] = p;
        int[] radical = new int[limit + 1], mu = new int[limit + 1];
        radical[1] = 1;
        mu[1] = 1;
        for (int v = 2; v <= limit; v++) {
            int p = spf[v], quotient = v / p;
            radical[v] = radical[quotient] * (quotient % p == 0 ? 1 : p);
            mu[v] = quotient % p == 0 ? 0 : -mu[quotient];
        }
        long[] powers = new long[n + 1];
        powers[0] = 1;
        for (int i = 0; i < n; i++) powers[i + 1] = powers[i] * 2 % MOD;
        int[] counts = new int[limit + 1], div = new int[64], sign = new int[64];
        for (int x : a) {
            int size = factors(radical[x], div, sign);
            for (int t = 1; t < size; t++) counts[div[t]]++;
        }
        // good subsequences = sum over squarefree d > 1 of -mu(d) * (2^count[d] - 1)
        long current = 0;
        for (int d = 2; d <= limit; d++)
            if (counts[d] > 0 && mu[d] != 0) current -= mu[d] * (powers[counts[d]] - 1);
        current = ((current % MOD) + MOD) % MOD;
        long answer = 0;
        for (int i = 0; i < q; i++) {
            int index = qx[i] - 1, value = qy[i], old = a[index];
            if (radical[old] != radical[value]) {
                int[][] changes = {{old, -1}, {value, 1}};
                for (int[] change : changes) {
                    int size = factors(radical[change[0]], div, sign);
                    for (int t = 1; t < size; t++) {
                        int d = div[t];
                        current += sign[t] * (powers[counts[d]] - 1);
                        counts[d] += change[1];
                        current -= sign[t] * (powers[counts[d]] - 1);
                    }
                }
                current = ((current % MOD) + MOD) % MOD;
            }
            a[index] = value;
            answer += current; // the per-update counts are summed without a final modulo
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const MOD = 1000000007

var spf []int

type term struct{ d, sign int }

// squarefree divisors d > 1 of a squarefree value, paired with mu(d)
func factors(value int, terms []term) []term {
	terms = append(terms[:0], term{1, 1})
	for value > 1 {
		p := spf[value]
		for value%p == 0 {
			value /= p
		}
		for t, size := 0, len(terms); t < size; t++ {
			terms = append(terms, term{terms[t].d * p, -terms[t].sign})
		}
	}
	return terms
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, q := next(), next()
	a := make([]int, n)
	qx, qy := make([]int, q), make([]int, q)
	limit := 1
	for i := range a {
		a[i] = next()
		limit = max(limit, a[i])
	}
	for i := 0; i < q; i++ {
		qx[i], qy[i] = next(), next()
		limit = max(limit, qy[i])
	}
	spf = make([]int, limit+1)
	for i := range spf {
		spf[i] = i
	}
	for p := 2; p*p <= limit; p++ {
		if spf[p] == p {
			for v := p * p; v <= limit; v += p {
				if spf[v] == v {
					spf[v] = p
				}
			}
		}
	}
	radical, mu := make([]int, limit+1), make([]int, limit+1)
	radical[1], mu[1] = 1, 1
	for v := 2; v <= limit; v++ {
		p, quotient := spf[v], v/spf[v]
		if quotient%p == 0 {
			radical[v], mu[v] = radical[quotient], 0
		} else {
			radical[v], mu[v] = radical[quotient]*p, -mu[quotient]
		}
	}
	powers := make([]int, n+1)
	powers[0] = 1
	for i := 0; i < n; i++ {
		powers[i+1] = powers[i] * 2 % MOD
	}
	counts := make([]int, limit+1)
	var terms []term
	for _, x := range a {
		terms = factors(radical[x], terms)
		for _, t := range terms[1:] {
			counts[t.d]++
		}
	}
	// good subsequences = sum over squarefree d > 1 of -mu(d) * (2^count[d] - 1)
	current := 0
	for d := 2; d <= limit; d++ {
		if counts[d] > 0 && mu[d] != 0 {
			current -= mu[d] * (powers[counts[d]] - 1)
		}
	}
	current = (current%MOD + MOD) % MOD
	answer := 0
	for i := 0; i < q; i++ {
		index, value := qx[i]-1, qy[i]
		old := a[index]
		if radical[old] != radical[value] {
			for _, change := range [2][2]int{{old, -1}, {value, 1}} {
				terms = factors(radical[change[0]], terms)
				for _, t := range terms[1:] {
					current += t.sign * (powers[counts[t.d]] - 1)
					counts[t.d] += change[1]
					current -= t.sign * (powers[counts[t.d]] - 1)
				}
			}
			current = (current%MOD + MOD) % MOD
		}
		a[index] = value
		answer += current // the per-update counts are summed without a final modulo
	}
	fmt.Println(answer)
}
